def countBound (n N : Nat) : Nat := n * (n - 1) / 2 + 1

def checkCase (N n : Nat) : Bool :=
  (countBound (n - 1) N < N + 1) && (N + 1 ≤ countBound n N)

def checkFragment : Bool :=
  checkCase 1 2 && checkCase 2 3 && checkCase 3 3 && checkCase 4 4 && checkCase 5 4

